'use client'

import * as React from 'react'

import { useStrings, type StringsOverrides } from './strings'

// The component brings its own styles. Without this a `gamestage-ui add`
// installs a working but unstyled deck, and `tsc --noEmit` passes on it.
import './swipe-deck.css'

import { Button } from './button'
import { CrossGlyph, StarGlyph, TickGlyph } from './glyphs'
import {
  heading,
  progress,
  release,
  tilt,
  DRAG_START_PX,
  type CardBox,
  type SwipeDeckDirection,
} from './swipe-deck-gestures'

export type { SwipeDeckDirection } from './swipe-deck-gestures'

/**
 * SwipeDeck: a stack of cards a player throws one at a time.
 *
 * Selector's swipe card is one question with a drawn second card behind it. It
 * leans a fixed amount once a direction is known and commits on release. This
 * is the deck that card stands for: the top card follows the finger, turns in
 * proportion to how far across it has gone, shows the badge of the answer it is
 * heading for, and either flies off when let go past the threshold or springs
 * back when not. The next card rises into its place.
 *
 * It reads the same tokens as Selector's card and draws the same badge, and it
 * speaks the same contract: `data-gs-interaction="swipe"` on the root and
 * `data-gs-swipe` naming the direction on everything bound to one.
 *
 * It decides nothing. A direction is reported through `onSwipe` and your app
 * says what it means. Left and right always answer; up answers only when you
 * name it in `answers`, and down never does.
 *
 * Every throw has a way in without a gesture: the answer buttons under the deck,
 * and the arrow keys on the focused card. A screen reader hears the card, its
 * position and how to answer it, then the outcome and the card that replaced it.
 */

export interface SwipeDeckCard {
  /** Identifies the card in `onSwipe` and `onUndo`. */
  id: string
  /** What the player reads: the question or the claim. */
  label: string
  /** A supporting line. Do not put meaning here that the label lacks. */
  detail?: string
  /** Art for the top of the card. Yours, rendered untouched. Decorative: the label carries the meaning. */
  media?: React.ReactNode
}

export interface SwipeDeckAnswers {
  /** The word for a throw left. Defaults to No. */
  left?: string
  /** The word for a throw right. Defaults to Yes. */
  right?: string
  /** The word for a throw up. Name it to turn the up answer on; leave it out and up does nothing. */
  up?: string
}

export interface SwipeDeckProps {
  /** The deck, top card first. Cards already thrown stay out of play while their ids are here. */
  cards: SwipeDeckCard[]
  /** What the deck is, for a screen reader: "Will this happen?". */
  label: string
  /** The words for each direction. Left and right always answer; up only when named. */
  answers?: SwipeDeckAnswers
  /** A card was thrown. The card is already on its way out; your app decides what the direction means. */
  onSwipe?: (cardId: string, direction: SwipeDeckDirection) => void
  /**
   * Pass it to offer Undo. The last card thrown comes back on top and this is
   * called with it, so your app can take its answer back. Absent, there is no
   * Undo control.
   */
  onUndo?: (cardId: string, direction: SwipeDeckDirection) => void
  /** What to show when every card has been thrown. Yours; a plain line is drawn if you leave it out. */
  empty?: React.ReactNode
  /** Not available. Nothing can be thrown, and the controls go flat. */
  disabled?: boolean
  /** Per-instance vocabulary, merged over the provider. */
  strings?: StringsOverrides
}

interface Thrown {
  id: string
  direction: SwipeDeckDirection
}

interface Leaving {
  key: number
  card: SwipeDeckCard
  direction: SwipeDeckDirection
  /** Where the card was when it was let go. */
  from: Pose
  box: CardBox
}

interface Pose {
  x: number
  y: number
  turn: number
}

interface Press {
  id: number
  x: number
  y: number
  lastX: number
  lastY: number
  lastT: number
  vx: number
  vy: number
  box: CardBox
  dragging: boolean
  pose: Pose
}

/** How many cards are drawn beneath the live one. */
const BENEATH = 2

/** The longest a throw or a spring can take, so a missing transitionend cannot strand it. */
const SETTLE_FALLBACK_MS = 600

const KEY_DIRECTION: Record<string, SwipeDeckDirection> = {
  ArrowLeft: 'left',
  ArrowRight: 'right',
  ArrowUp: 'up',
}

const reducedMotion = () =>
  typeof window !== 'undefined' && Boolean(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)

const poseTransform = ({ x, y, turn }: Pose) => `translate(${x}px, ${y}px) rotate(${turn}deg)`

/** How far past the screen's edge a thrown card is taken, so its corner is gone too. */
const EXIT_MARGIN_PX = 48

/**
 * Where a thrown card ends up: off the screen, carried on the way it was going.
 * The distance is measured from where the card is to the edge of the viewport
 * rather than from the card's own size, so a card thrown from the middle of a
 * wide screen leaves it rather than stopping short and vanishing in view.
 */
function landing(direction: SwipeDeckDirection, from: Pose, rect: DOMRect, box: CardBox): Pose {
  const viewWidth = typeof window !== 'undefined' ? window.innerWidth : 0
  if (direction === 'up') {
    const travel = Math.max(rect.bottom + EXIT_MARGIN_PX, box.height * 1.2)
    return { x: from.x * 1.5, y: from.y - travel, turn: from.turn }
  }
  const sign = direction === 'right' ? 1 : -1
  const travel =
    sign > 0
      ? Math.max(viewWidth - rect.left + EXIT_MARGIN_PX, box.width * 1.2)
      : Math.max(rect.right + EXIT_MARGIN_PX, box.width * 1.2)
  return { x: from.x + sign * travel, y: from.y * 1.5, turn: from.turn + sign * 12 }
}

export function SwipeDeck(props: SwipeDeckProps) {
  const { strings, ...componentProps } = props
  const copy = useStrings(strings)
  const { cards, label, answers = {}, onSwipe, onUndo, empty, disabled = false } = componentProps

  const words: Record<SwipeDeckDirection, string | undefined> = {
    left: answers.left ?? copy['swipe-deck.no'],
    right: answers.right ?? copy['swipe-deck.yes'],
    up: answers.up,
  }
  const allowUp = words.up !== undefined
  const bound: SwipeDeckDirection[] = allowUp ? ['left', 'up', 'right'] : ['left', 'right']
  const directionWord: Record<SwipeDeckDirection, string> = {
    left: copy['swipe-deck.left'],
    right: copy['swipe-deck.right'],
    up: copy['swipe-deck.up'],
  }

  const [thrown, setThrown] = React.useState<Thrown[]>([])
  const [leaving, setLeaving] = React.useState<Leaving[]>([])
  const [announcement, setAnnouncement] = React.useState('')
  const leavingKey = React.useRef(0)

  const thrownIds = new Set(thrown.map((entry) => entry.id))
  const inPlay = cards.filter((card) => !thrownIds.has(card.id))
  const top = inPlay[0]
  const beneath = inPlay.slice(1, 1 + BENEATH)
  const isEmpty = !top

  const cardRef = React.useRef<HTMLDivElement | null>(null)
  const emptyRef = React.useRef<HTMLDivElement | null>(null)
  const press = React.useRef<Press | null>(null)
  // Set when the player answered from the card itself, so focus follows them
  // to the next card rather than falling to the page.
  const focusNext = React.useRef(false)

  React.useEffect(() => {
    if (!focusNext.current) return
    focusNext.current = false
    ;(cardRef.current ?? emptyRef.current)?.focus()
  }, [top?.id])

  // -- drawing the live card where the finger has it -----------------------
  const draw = (el: HTMLElement, dx: number, dy: number, box: CardBox): Pose => {
    const pose = { x: dx, y: dy, turn: reducedMotion() ? 0 : tilt(dx, box.width) }
    el.style.transform = poseTransform(pose)
    const direction = heading(dx, dy, allowUp)
    const amount = progress(dx, dy, box, allowUp)
    for (const d of ['left', 'right', 'up'] as const) {
      el.style.setProperty(`--gs-swipe-deck-${d}`, d === direction ? String(amount) : '0')
    }
    if (direction) el.setAttribute('data-gs-swipe', direction)
    else el.removeAttribute('data-gs-swipe')
    return pose
  }

  const clear = (el: HTMLElement) => {
    el.style.removeProperty('transform')
    for (const d of ['left', 'right', 'up'] as const) el.style.removeProperty(`--gs-swipe-deck-${d}`)
    el.removeAttribute('data-gs-swipe')
    el.classList.remove('gs-swipe-deck__card--dragging')
  }

  const springBack = (el: HTMLElement) => {
    el.classList.add('gs-swipe-deck__card--settling')
    clear(el)
    let done = false
    const finish = (event?: TransitionEvent) => {
      if (event && event.target !== el) return
      if (done) return
      done = true
      el.classList.remove('gs-swipe-deck__card--settling')
      el.removeEventListener('transitionend', finish)
    }
    el.addEventListener('transitionend', finish)
    window.setTimeout(() => finish(), SETTLE_FALLBACK_MS)
  }

  // -- committing an answer -------------------------------------------------
  function commit(direction: SwipeDeckDirection, from: Pose = { x: 0, y: 0, turn: 0 }) {
    if (!top || disabled) return
    if (direction === 'up' && !allowUp) return
    const el = cardRef.current
    const box = el ? { width: el.offsetWidth, height: el.offsetHeight } : { width: 0, height: 0 }
    if (el) clear(el)
    leavingKey.current += 1
    setLeaving((list) => [...list, { key: leavingKey.current, card: top, direction, from, box }])
    setThrown((list) => [...list, { id: top.id, direction }])
    const next = inPlay[1]
    const outcome = copy['swipe-deck.outcome'](top.label, words[direction] ?? '')
    setAnnouncement(copy['swipe-deck.after'](outcome, next ? next.label : copy['swipe-deck.empty']))
    onSwipe?.(top.id, direction)
  }

  function undo() {
    const last = thrown[thrown.length - 1]
    if (!last || disabled) return
    const card = cards.find((entry) => entry.id === last.id)
    setThrown((list) => list.slice(0, -1))
    setLeaving((list) => list.filter((entry) => entry.card.id !== last.id))
    if (card) setAnnouncement(copy['swipe-deck.undone'](card.label))
    focusNext.current = true
    onUndo?.(last.id, last.direction)
  }

  // -- the gesture ------------------------------------------------------------
  const gesture = {
    onPointerDown: (event: React.PointerEvent<HTMLDivElement>) => {
      if (disabled || !top) return
      if (event.pointerType === 'mouse' && event.button !== 0) return
      const el = event.currentTarget
      el.setPointerCapture?.(event.pointerId)
      press.current = {
        id: event.pointerId,
        x: event.clientX,
        y: event.clientY,
        lastX: event.clientX,
        lastY: event.clientY,
        lastT: event.timeStamp,
        vx: 0,
        vy: 0,
        box: { width: el.offsetWidth, height: el.offsetHeight },
        dragging: false,
        pose: { x: 0, y: 0, turn: 0 },
      }
    },
    onPointerMove: (event: React.PointerEvent<HTMLDivElement>) => {
      const p = press.current
      if (!p || p.id !== event.pointerId) return
      const dx = event.clientX - p.x
      const dy = event.clientY - p.y
      if (!p.dragging) {
        if (Math.hypot(dx, dy) < DRAG_START_PX) return
        p.dragging = true
        event.currentTarget.classList.remove('gs-swipe-deck__card--settling')
        event.currentTarget.classList.add('gs-swipe-deck__card--dragging')
      }
      // Speed is smoothed over the last few samples, so one jittery event at
      // the moment of release cannot turn a slow drag into a flick.
      const dt = event.timeStamp - p.lastT
      if (dt > 0) {
        p.vx = p.vx * 0.5 + ((event.clientX - p.lastX) / dt) * 0.5
        p.vy = p.vy * 0.5 + ((event.clientY - p.lastY) / dt) * 0.5
      }
      p.lastX = event.clientX
      p.lastY = event.clientY
      p.lastT = event.timeStamp
      p.pose = draw(event.currentTarget, dx, dy, p.box)
    },
    onPointerUp: (event: React.PointerEvent<HTMLDivElement>) => {
      const p = press.current
      if (!p || p.id !== event.pointerId) return
      press.current = null
      if (!p.dragging) return
      const dx = event.clientX - p.x
      const dy = event.clientY - p.y
      // A pointer that stopped before letting go has no speed left.
      const still = event.timeStamp - p.lastT > 80
      const verdict = release({
        dx,
        dy,
        vx: still ? 0 : p.vx,
        vy: still ? 0 : p.vy,
        box: p.box,
        allowUp,
      })
      if (verdict) commit(verdict, p.pose)
      else springBack(event.currentTarget)
    },
    // The browser took the pointer: a scroll, a system gesture, a call coming
    // in. Nothing was answered, so the card goes back.
    onPointerCancel: (event: React.PointerEvent<HTMLDivElement>) => {
      const p = press.current
      if (!p || p.id !== event.pointerId) return
      press.current = null
      springBack(event.currentTarget)
    },
  }

  const nameOf = (card: SwipeDeckCard) => {
    const parts = [card.label]
    if (card.detail) parts.push(card.detail)
    parts.push(copy['swipe-deck.position'](cards.indexOf(card) + 1, cards.length))
    for (const direction of bound) {
      parts.push(copy['swipe-deck.swipeFor'](directionWord[direction], words[direction] ?? ''))
    }
    return parts.join(', ')
  }

  const badges = bound.map((direction) => (
    <span
      key={direction}
      className="gs-swipe-deck__badge"
      data-gs-scope="swipe-deck"
      data-gs-part="glyph"
      data-gs-swipe={direction}
      data-gs-animates="emphasis"
      aria-hidden="true"
    >
      {direction === 'left' ? <CrossGlyph /> : direction === 'right' ? <TickGlyph /> : <StarGlyph />}
    </span>
  ))

  const body = (card: SwipeDeckCard) => (
    <>
      {card.media ? (
        <div className="gs-swipe-deck__media" data-gs-scope="swipe-deck" data-gs-part="media" aria-hidden="true">
          {card.media}
        </div>
      ) : null}
      <div className="gs-swipe-deck__words">
        <span className="gs-swipe-deck__label" data-gs-scope="swipe-deck" data-gs-part="label">
          {card.label}
        </span>
        {card.detail ? (
          <span className="gs-swipe-deck__detail" data-gs-scope="swipe-deck" data-gs-part="note">
            {card.detail}
          </span>
        ) : null}
      </div>
      {badges}
    </>
  )

  return (
    <div
      className={allowUp ? 'gs-swipe-deck gs-swipe-deck--up' : 'gs-swipe-deck'}
      data-gs-component="swipe-deck"
      data-gs-interaction="swipe"
      data-gs-empty={isEmpty ? 'true' : undefined}
      data-gs-disabled={disabled ? 'true' : undefined}
      role="group"
      aria-label={label}
      aria-disabled={disabled || undefined}
    >
      <div className="gs-swipe-deck__stack">
        {/* Drawn deepest first, so the live card is last in the source and on top. */}
        {[...beneath].reverse().map((card) => (
          <div
            key={card.id}
            className="gs-swipe-deck__card"
            data-gs-scope="swipe-deck"
            data-gs-part="card"
            data-gs-item={card.id}
            data-gs-elevation="raised"
            data-gs-animates="motion"
            style={{ '--gs-swipe-deck-depth': beneath.indexOf(card) + 1 } as React.CSSProperties}
            aria-hidden="true"
          >
            {body(card)}
          </div>
        ))}
        {top ? (
          <div
            key={top.id}
            ref={cardRef}
            className="gs-swipe-deck__card"
            data-gs-scope="swipe-deck"
            data-gs-part="card"
            data-gs-item={top.id}
            data-gs-active="true"
            data-gs-elevation="raised"
            data-gs-animates="motion"
            style={{ '--gs-swipe-deck-depth': 0 } as React.CSSProperties}
            role="group"
            aria-roledescription={copy['swipe-deck.roledescription']}
            aria-label={nameOf(top)}
            aria-disabled={disabled || undefined}
            tabIndex={disabled ? -1 : 0}
            onKeyDown={(event) => {
              const direction = KEY_DIRECTION[event.key]
              if (!direction || (direction === 'up' && !allowUp)) return
              event.preventDefault()
              focusNext.current = true
              commit(direction)
            }}
            {...gesture}
          >
            {body(top)}
          </div>
        ) : (
          <div
            ref={emptyRef}
            className="gs-swipe-deck__empty"
            data-gs-scope="swipe-deck"
            data-gs-part="empty"
            tabIndex={-1}
          >
            {empty ?? <span className="gs-swipe-deck__empty-line">{copy['swipe-deck.empty']}</span>}
          </div>
        )}
        {leaving.map((entry) => (
          <LeavingCard
            key={`leaving-${entry.key}`}
            entry={entry}
            onDone={() => setLeaving((list) => list.filter((item) => item.key !== entry.key))}
          >
            {body(entry.card)}
          </LeavingCard>
        ))}
      </div>

      <div className="gs-swipe-deck__actions" data-gs-scope="swipe-deck" data-gs-part="actions">
        {!isEmpty
          ? bound.map((direction) => (
              <Button
                key={direction}
                variant="secondary"
                className="gs-swipe-deck__answer"
                // Three answers share a phone's width, so a long word is set
                // smaller rather than cut: "Not sure" was drawn "NOT S..." at 390.
                labelFit="shrink"
                data-gs-scope="swipe-deck"
                data-gs-part="commit"
                data-gs-swipe={direction}
                disabled={disabled}
                onClick={() => commit(direction)}
              >
                {words[direction]}
              </Button>
            ))
          : null}
      </div>

      {/* Undo has a row of its own, there from the start whenever you offer it,
          so the answers never shift sideways to make room for it. Until there
          is a throw to take back it is disabled, which also hides it. */}
      {onUndo ? (
        <div className="gs-swipe-deck__more">
          <Button
            variant="tertiary"
            className="gs-swipe-deck__undo"
            data-gs-scope="swipe-deck"
            data-gs-part="undo"
            disabled={disabled || thrown.length === 0}
            onClick={undo}
          >
            {copy['swipe-deck.undo']}
          </Button>
        </div>
      ) : null}

      {/* Always present and always polite, so the outcome of a throw is heard
          whichever way it was made. */}
      <span
        className="gs-swipe-deck__hidden"
        data-gs-scope="swipe-deck"
        data-gs-part="announcement"
        aria-live="polite"
      >
        {announcement}
      </span>
    </div>
  )
}

/**
 * A thrown card on its way out. It is drawn apart from the deck, so the next
 * card can rise while this one flies, and your app can drop the card from
 * `cards` in `onSwipe` without cutting the throw short.
 *
 * It starts where the finger let go and travels off the screen the way it was
 * going, still turning, and is removed when that travel ends. It does not fade
 * on the way: the first version faded on the same fast-start curve as the
 * travel and was all but invisible a third of the way through, which read as
 * the card blinking out at the line. Under reduced motion it does not travel
 * or turn: it fades where it stands.
 */
function LeavingCard({
  entry,
  onDone,
  children,
}: {
  entry: Leaving
  onDone: () => void
  children: React.ReactNode
}) {
  const ref = React.useRef<HTMLDivElement | null>(null)
  // Read once, when the throw starts. Under reduced motion the card only
  // fades, and a fade is emphasis: it survives the rule that zeroes movement.
  const [still] = React.useState(reducedMotion)
  const done = React.useRef(onDone)
  done.current = onDone

  React.useLayoutEffect(() => {
    const el = ref.current
    if (!el) return
    el.style.transform = poseTransform(entry.from)
    // Read layout once so the starting pose is committed before the landing
    // is set; without it the browser skips straight to the end.
    const rect = el.getBoundingClientRect()
    el.classList.add('gs-swipe-deck__card--thrown')
    if (still) el.style.opacity = '0'
    else el.style.transform = poseTransform(landing(entry.direction, entry.from, rect, entry.box))
    // The throw is over when the property that carries it has finished: the
    // travel, or under reduced motion the fade. Until then the card stays in
    // the page, so the player sees it go rather than blink out.
    const carries = still ? 'opacity' : 'transform'
    let finished = false
    const finish = (event?: TransitionEvent) => {
      if (event && (event.target !== el || (event.propertyName && event.propertyName !== carries))) return
      if (finished) return
      finished = true
      done.current()
    }
    el.addEventListener('transitionend', finish)
    const timer = window.setTimeout(() => finish(), SETTLE_FALLBACK_MS)
    return () => {
      el.removeEventListener('transitionend', finish)
      window.clearTimeout(timer)
    }
  }, [entry, still])

  return (
    <div
      ref={ref}
      className="gs-swipe-deck__card gs-swipe-deck__card--leaving"
      data-gs-scope="swipe-deck"
      data-gs-part="card"
      data-gs-item={entry.card.id}
      data-gs-leaving="true"
      data-gs-swipe={entry.direction}
      data-gs-elevation="raised"
      data-gs-animates={still ? 'emphasis' : 'motion'}
      style={{ '--gs-swipe-deck-depth': 0, [`--gs-swipe-deck-${entry.direction}`]: 1 } as React.CSSProperties}
      aria-hidden="true"
    >
      {children}
    </div>
  )
}

/**
 * The decisions behind a swipe deck's gesture, as numbers in and a verdict out.
 *
 * Kept apart from the component, as story-gestures.ts is for the story, so each
 * threshold is a tested fact rather than a line buried in a pointer handler. The
 * component measures and moves the card; this file decides what the movement
 * means. GSUI-301.
 */

export type SwipeDeckDirection = 'left' | 'right' | 'up'

/** Past this share of the card's width, letting go throws it sideways. */
export const COMMIT_SHARE_X = 0.3

/** Past this share of the card's height, letting go throws it upwards. */
export const COMMIT_SHARE_Y = 0.25

/**
 * The distance a throw needs, whatever the card measures. A card in a narrow
 * column would otherwise commit on a twitch.
 */
export const COMMIT_MIN_PX = 72

/**
 * A flick this fast throws the card however short the travel, in pixels a
 * millisecond. The same figure the story uses for a downward flick, because it
 * is the same thumb.
 */
export const FLICK_PX_PER_MS = 0.5

/** A flick still has to travel this far, so a twitch commits nothing. */
export const FLICK_MIN_PX = 32

/** The turn the card makes at a full card-width of sideways travel. */
export const MAX_TILT_DEG = 18

/** How far a pointer moves before it is a drag rather than a press. */
export const DRAG_START_PX = 4

/** Card size, measured by the component on pointer down. */
export interface CardBox {
  width: number
  height: number
}

/** The distance each direction needs for this card. */
export function thresholds(box: CardBox): { x: number; y: number } {
  return {
    x: Math.max(COMMIT_MIN_PX, box.width * COMMIT_SHARE_X),
    y: Math.max(COMMIT_MIN_PX, box.height * COMMIT_SHARE_Y),
  }
}

/**
 * Which way the card is heading. Up only when the deck takes an up answer and
 * the drag is more up than across; down is never an answer, so a downward drag
 * reads by its sideways part.
 */
export function heading(dx: number, dy: number, allowUp: boolean): SwipeDeckDirection | null {
  if (allowUp && dy < 0 && -dy > Math.abs(dx)) return 'up'
  if (dx === 0) return null
  return dx > 0 ? 'right' : 'left'
}

/** The turn for a given sideways travel: proportional, and capped. */
export function tilt(dx: number, width: number): number {
  if (!(width > 0)) return 0
  const turn = (dx / width) * MAX_TILT_DEG
  return Math.max(-MAX_TILT_DEG, Math.min(MAX_TILT_DEG, turn))
}

/**
 * How far towards committing the drag is, 0 to 1, in the direction it is
 * heading. This is the badge's opacity: it reaches full at the threshold, so
 * the player sees the answer land before letting go.
 */
export function progress(dx: number, dy: number, box: CardBox, allowUp: boolean): number {
  const direction = heading(dx, dy, allowUp)
  if (!direction) return 0
  const { x, y } = thresholds(box)
  const travel = direction === 'up' ? -dy / y : Math.abs(dx) / x
  return Math.max(0, Math.min(1, travel))
}

export interface ReleaseInput {
  dx: number
  dy: number
  /** Speed at release along each axis, pixels a millisecond, signed. */
  vx: number
  vy: number
  box: CardBox
  allowUp: boolean
}

/**
 * What letting go means: a direction to throw the card, or null to spring it
 * back. One verdict, so the handler cannot act twice.
 *
 * A flick only counts in the direction the card is already heading, so a
 * player who drags right and snaps back left at the last moment gets the card
 * back rather than a No they did not mean.
 */
export function release(input: ReleaseInput): SwipeDeckDirection | null {
  const { dx, dy, vx, vy, box, allowUp } = input
  const direction = heading(dx, dy, allowUp)
  if (!direction) return null
  const { x, y } = thresholds(box)
  if (direction === 'up') {
    if (-dy >= y) return 'up'
    return -vy >= FLICK_PX_PER_MS && -dy >= FLICK_MIN_PX ? 'up' : null
  }
  const travel = Math.abs(dx)
  if (travel >= x) return direction
  const along = direction === 'right' ? vx : -vx
  return along >= FLICK_PX_PER_MS && travel >= FLICK_MIN_PX ? direction : null
}

/* SwipeDeck: a stack of cards a player throws one at a time.

   The card is Selector's swipe card (specimen 1j) made real: the same raised
   surface, the same high edge, the same radius and depth, and the same badge,
   a ring in the answer's colour turned a little in the top corner. What is new
   is that it moves: it follows the finger, turns with the sideways travel, and
   flies off or springs back.

   Movement is timed by tokens and carries data-gs-animates="motion", so under
   reduced motion every transform below stops dead without this file saying so.
   The badge's opacity is emphasis and survives.

   The deck draws over its own edges while a card is dragged or thrown. Put it
   in a screen that clips, as Stage does, so a thrown card leaves the screen
   rather than widening the page. */

.gs-swipe-deck {
  display: grid;
  gap: var(--gs-space-4);
  min-width: 0;
  /* A swipe card is a phone card wherever it sits. Without a ceiling the card
     took the width of whatever held it and was a landscape slab on a desktop,
     1650px across in the Gallery. Override --gs-swipe-deck-max-width to size
     it for your screen; the deck centres itself in what is left. */
  width: 100%;
  max-width: var(--gs-swipe-deck-max-width, calc(var(--gs-size-touch-min) * 8));
  margin-inline: auto;
  color: var(--gs-color-ink);
}

/* -- the stack ------------------------------------------------------------- */
/* One grid cell, every card in it, so the stack is as tall as its tallest card
   and nothing below it moves when a card leaves. */
.gs-swipe-deck__stack {
  display: grid;
  position: relative;
  /* Room for the cards set down beneath the live one. */
  padding-bottom: calc(var(--gs-space-3) * 2);
}

.gs-swipe-deck__stack > * {
  grid-area: 1 / 1;
}

.gs-swipe-deck__card {
  position: relative;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: var(--gs-space-4);
  min-width: 0;
  /* Portrait, as a card in the hand is. Content longer than the shape allows
     grows the card rather than spilling out of it. */
  aspect-ratio: var(--gs-swipe-deck-aspect, 3 / 4);
  padding: var(--gs-space-4);
  background: var(--gs-color-surface-raised);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge-high);
  border-radius: var(--gs-radius-xl);
  box-shadow: var(--gs-depth-raised);
  user-select: none;
  -webkit-user-select: none;

  /* Each card beneath the live one is set down by a step and in by a step,
     exactly as Selector's drawn second card is. The depth is set per card. */
  transform:
    translateY(calc(var(--gs-swipe-deck-depth, 0) * var(--gs-space-3)))
    scale(calc(1 - var(--gs-swipe-deck-depth, 0) * 0.05));
  transform-origin: 50% 100%;

  /* The rise of the next card when the one above it leaves. */
  transition: transform var(--gs-motion-reorder) var(--gs-motion-ease-reorder);
}

/* The live card. A drag that is mostly vertical is left to the page to scroll,
   unless up is an answer, in which case the card takes every direction. */
.gs-swipe-deck__card[data-gs-active] {
  cursor: grab;
  touch-action: pan-y;
}

.gs-swipe-deck--up .gs-swipe-deck__card[data-gs-active] {
  touch-action: none;
}

.gs-swipe-deck__card[data-gs-active]:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-focus-color, var(--gs-color-ink-solid));
  outline-offset: var(--gs-focus-offset, 3px);
}

.gs-swipe-deck[data-gs-disabled] .gs-swipe-deck__card[data-gs-active] {
  cursor: default;
}

/* Under the finger the card goes exactly where it is put, so nothing is timed. */
.gs-swipe-deck__card--dragging {
  cursor: grabbing;
  transition: none;
}

/* Let go short of the line: back to rest with a little overshoot. */
.gs-swipe-deck__card--settling {
  transition: transform var(--gs-motion-pop) var(--gs-motion-ease-pop);
}

/* Thrown: drawn over the deck, out of the way of presses, and on its way off
   the screen. */
.gs-swipe-deck__card--leaving {
  z-index: 1;
  pointer-events: none;
}

.gs-swipe-deck__card--thrown {
  /* The throw's own pair, motion.throw and motion.ease.throw: 300ms, carrying
     on at the finger's speed and easing as it goes. Travel only, no fade on
     the way. GSUI-302. */
  transition: transform var(--gs-motion-throw) var(--gs-motion-ease-throw);
}

.gs-swipe-deck__card--thrown[data-gs-animates='emphasis'] {
  transition: opacity var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis);
}

/* -- what is on a card ----------------------------------------------------- */

.gs-swipe-deck__media {
  overflow: hidden;
  border-radius: var(--gs-radius-lg);
  aspect-ratio: 16 / 9;
  background: var(--gs-color-surface);
}

.gs-swipe-deck__media > img,
.gs-swipe-deck__media > video,
.gs-swipe-deck__media > svg {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.gs-swipe-deck__words {
  display: grid;
  gap: var(--gs-space-2);
  /* Centred in what the media leaves, so a card with no art reads as a
     question on a card rather than a line at the foot of an empty panel. */
  margin-block: auto;
}

.gs-swipe-deck__label {
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: var(--gs-type-title-line-height);
  overflow-wrap: anywhere;
}

.gs-swipe-deck__detail {
  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-body-font-weight);
  line-height: var(--gs-type-body-line-height);
  color: var(--gs-color-ink-secondary-solid);
}

/* -- the badge ------------------------------------------------------------- */
/* Selector's badge: a ring in the answer's colour with its mark, turned a
   little. Here its opacity is the drag's progress towards the line, set on the
   card as --gs-swipe-deck-left, -right or -up, so it is fully drawn at the
   moment letting go would commit. Cross on the left, tick on the right, star
   in the middle for an up answer, all along the top edge where the text is not. */
.gs-swipe-deck__badge {
  position: absolute;
  top: var(--gs-space-4);
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--gs-size-control-medium);
  height: var(--gs-size-control-medium);
  box-sizing: border-box;
  font-size: var(--gs-size-icon-utility);
  background: var(--gs-color-surface-raised-solid);
  border: var(--gs-stroke-selected) solid currentColor;
  border-radius: var(--gs-radius-full);
  pointer-events: none;
}

/* The badge sits on the side the card is heading away from, as a stamp does,
   so the finger never covers it. */
.gs-swipe-deck__badge[data-gs-swipe='left'] {
  right: var(--gs-space-4);
  color: var(--gs-color-negative-ink, var(--gs-color-negative-solid));
  transform: rotate(12deg);
  opacity: var(--gs-swipe-deck-left, 0);
}

.gs-swipe-deck__badge[data-gs-swipe='right'] {
  left: var(--gs-space-4);
  color: var(--gs-color-positive-ink, var(--gs-color-positive-solid));
  transform: rotate(-12deg);
  opacity: var(--gs-swipe-deck-right, 0);
}

.gs-swipe-deck__badge[data-gs-swipe='up'] {
  left: 50%;
  margin-left: calc(var(--gs-size-control-medium) / -2);
  color: var(--gs-color-reward-ink, var(--gs-color-reward-solid));
  opacity: var(--gs-swipe-deck-up, 0);
}

/* Springing back, the badge fades with the card rather than vanishing. */
.gs-swipe-deck__card--settling .gs-swipe-deck__badge {
  transition: opacity var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis);
}

/* -- empty ----------------------------------------------------------------- */
/* The same footprint as a card, so the controls below do not jump when the
   last card goes. */
.gs-swipe-deck__empty {
  box-sizing: border-box;
  display: grid;
  place-items: center;
  aspect-ratio: var(--gs-swipe-deck-aspect, 3 / 4);
  padding: var(--gs-space-4);
  text-align: center;
  border: var(--gs-stroke-ui) dashed var(--gs-color-edge-solid);
  border-radius: var(--gs-radius-xl);
}

.gs-swipe-deck__empty:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-focus-color, var(--gs-color-ink-solid));
  outline-offset: var(--gs-focus-offset, 3px);
}

.gs-swipe-deck__empty-line {
  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-body-font-weight);
  color: var(--gs-color-ink-secondary-solid);
}

/* -- the answers ----------------------------------------------------------- */
/* One button per bound direction, in the order the directions sit: left, up,
   right. Each takes an equal share, so No is under the left edge and Yes under
   the right, where a throw would send the card. */
.gs-swipe-deck__actions {
  display: flex;
  gap: var(--gs-space-gap);
  min-height: var(--gs-size-touch-min);
}

.gs-swipe-deck__answer {
  flex: 1 1 0;
  min-width: 0;
}

/* Three answers share a phone's width. A button's own side padding is sized
   for one action on a row, and left a third of a 96px button for its word. */
.gs-swipe-deck .gs-swipe-deck__answer {
  padding-inline: var(--gs-space-2);
}

.gs-swipe-deck__more {
  display: flex;
  justify-content: center;
  min-height: var(--gs-size-touch-min);
}

/* Nothing to take back yet. The row keeps its height, so nothing moves when
   the first throw brings Undo in, and a hidden control takes no focus. */
.gs-swipe-deck__undo[disabled] {
  visibility: hidden;
}

.gs-swipe-deck__hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}
